import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"58、【兌】 兌下兌上","description":"周易闡真 - 58、【兌】 兌下兌上","frontmatter":{"title":"58、【兌】 兌下兌上","description":"周易闡真 - 58、【兌】 兌下兌上"},"headers":[],"relativePath":"classics/chanzhen/059.md","filePath":"classics/chanzhen/059.md"}'),s={name:"classics/chanzhen/059.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：兌，說也。剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞。說以犯難，民忘其死。說之大，民勸矣哉！</p></blockquote><h1 id="_58、【兌】-兌下兌上" tabindex="-1">58、【兌】 兌下兌上 <a class="header-anchor" href="#_58、【兌】-兌下兌上" aria-label="Permalink to “58、【兌】 兌下兌上”">​</a></h1><p>初九：和兌，吉。</p><p>九二：孚兌，吉，悔亡。</p><p>六三：來兌，兇。</p><p>九四：商兌，未寧介疾，有喜。</p><p>九五：孚於剝，有厲。</p><p>上六：引兌。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：麗澤，兌。君子以朋友講習。</p><p>兌者，和悅也，取象為澤。上兌澤，下兌澤，是兩澤相麗，彼此浸潤，兌悅之象也。</p><p>君子有見於此，知其性命之道最深，毫髮之差，千里之失。以是與朋友講習焉。朋友者，同道同心之人。理不講不明，講不習不精，此講彼習，彼講此習，反覆辯論，來往追究，刻入深進，而後有得。蓋一人之知識有限，眾人之意見無窮。我有不知，借朋友以講明；朋友不知，借我以講明。講而又習，不知者必知，不精者必精，得心應手，何患不到深造自得之地乎!</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>兌者，悅也。卦體二陽在下，一陰在上，虛於外而實於內，取象為澤，其德為悅。澤之為物，所以浸潤萬物，悅成萬物者，內悅外悅，自內而達外，由外以通內，內外相合，彼此無間，故謂兌。此悅於修道之卦，承上旅卦而來。旅者，以止行明，明不妄用，有志於道，而一切外物不得移之。</p><p>夫志於道，悅於道者也。悅於道，即能行其道，是以兌有亨道也。然悅於道雖亨，尤利於貞。貞則利，而遂其悅；不貞則不利，而敗其悅。如卦象上兌下兌，六爻相併。</p><p>下兌者，內悅也；上兌者，外悅也。內悅實，則外悅亦實；內悅虛，則外悅亦虛。實者悅之真，虛者悅之假，真者悅之久遠，假者悅之不長，利於貞者，正在於此。真正修道之人，不悅於聲色貨利，而悅於仁義道德，自有真悅，不務假悅，一步一趨，皆從身心性命上用工夫。悅於始自能全於終，悅而未有不亨，亨而未有不利者也。</p><p>初九，剛而居正，悅出自然，絕無勉強，是謂和兌。悅至於和，能大能小，不傷其剛，自致其吉。此剛而有守之悅也。</p><p>九二，誠實於中，內有主宰，悅於真而不悅假，一切虛幻之事，不得而動之，其吉在內，有何悔之不亡乎?此剛而得中之悅也。</p><p>六三，柔而不中不正，不悅於內，而悅於外，舍其真而逐於假，為修道者之障礙，終於不能入道，其兇可知。此柔而務外之悅也。</p><p>九四，剛以柔用，擬之而後言，議之而後動，擬議以成其變化，是謂商兌。兌至於商，不敢順悅，戒慎恐懼，不寧於處，非禮不履，如得介疾，終必有喜而遂其悅矣。此剛而能柔之悅也。</p><p>九五，自滿自盈，能剛悅而不能柔悅，終必敗。剛而不悅，是孚於剝，必有厲矣。大凡天資聰明之人，全在虛心下氣，親近有道之士，方能受益。若挾貴挾才，喜奉承而惡直言，親小人而遠君子，過日增而善日減，惡漸長而德漸消，不厲而自致厲，所謂“如有周公之才之美，使驕且吝，其餘不足觀也已”。此剛而自滿之悅也。</p><p>上六，悅之見外，巧言令色，人不悅而引人以悅之，此等之輩，無而為有，虛而為盈，不肯自思己錯，更將錯路教人，終於不能悅人，終於人不悅我。此柔而務外之悅也。</p><p>然則悅有真假，是非不同，吉凶悔吝不一，總以悅之得正為貴。正則亨，不正則不亨。修道者，可不以正而悅哉!</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
